import { Component, inject } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { AutorizacionesListComponent } from '../../../../shared/components/autorizaciones-list/autorizaciones-list.component';
import { SeccionAutorizadas } from '../../../../shared/models/solicitud.model';
import { SeccionTramite } from '../../../../shared/models/seccion-tramite.enum';

@Component({
  selector: 'app-tramites-list',
  imports: [AutorizacionesListComponent],
  templateUrl: './tramites-list.component.html',
})
export class TramitesListComponent {

  private readonly route = inject(ActivatedRoute);
  readonly seccion = (this.route.snapshot.data['seccion'] as SeccionAutorizadas) ?? 'asignar';
  readonly title = this.titulo();
  readonly statusPreset = this.seccion === 'asignar' ? ['Autorizada'] : undefined;
  readonly seccionTramite = this.seccion !== 'asignar' ? (this.seccion as SeccionTramite) : undefined;
  readonly accionPrincipal = this.computarAccion();

  private computarAccion(): { label: string; route: string } | undefined {
    switch (this.seccion) {
      case 'asignar': return { label: 'Asignar trámites', route: '/ejecutivos/solicitudes' };
      case SeccionTramite.POR_APROBAR:
      case SeccionTramite.APROBADAS:
      case SeccionTramite.NO_APROBADAS:
        return { label: 'Revisar trámites', route: '/ejecutivos/autorizadas' };
      default: return undefined;
    }
  }

  readonly mostrarMetricas = this.seccion === SeccionTramite.APROBADAS || this.seccion === SeccionTramite.NO_APROBADAS;
  readonly verBaseRoute = 'ejecutivos/solicitudes';

  private titulo(): string {
    switch (this.seccion) {
      case 'asignar': return 'Solicitudes autorizadas — Asignar trámites';
      case SeccionTramite.POR_APROBAR: return 'Trámites por aprobar';
      case SeccionTramite.APROBADAS: return 'Trámites aprobados';
      case SeccionTramite.NO_APROBADAS: return 'Trámites no aprobados';
      default: return '';
    }
  }
}
